mapper.select:
SELECT distinct A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, nvl(A.FINPROD_ID,'') || ',' || nvl(C.CASH_ID,'') ||',' || nvl(A.FINPROD_ABBR,'') object FROM FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID,
FIN_CASH_INFO C WHERE A.FINPROD_ID = C.FINPROD_ID AND A.OPERATION_TYPE = #{ISSUE_MODE_02,jdbcType=VARCHAR} AND C.CASH_TYPE_1=#{CASH_TYPE_1_06,jdbcType=VARCHAR}
AND (A.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT (#{search,jdbcType=VARCHAR},'%')) or A.FINPROD_ABBR LIKE CONCAT('%',CONCAT (#{search,jdbcType=VARCHAR},'%')) )
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}
